PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?feature ?geometry
WHERE {
    ?feature rdf:type geo:Feature .
    ?geometry rdf:type geo:Geometry .
    FILTER NOT EXISTS { 
        ?feature owl:equivalentClass ?g .
        ?g rdf:type geo:Geometry 
    }
}

PREFIX saref4city: <https://w3id.org/def/saref4city#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?administrativeArea ?relatedAdministrativeArea 
WHERE {
    ?administrativeArea rdf:type saref4city:AdministrativeArea .
    ?relatedAdministrativeArea rdf:type saref4city:AdministrativeArea .
    FILTER (?administrativeArea != ?relatedAdministrativeArea) .
    { 
        ?administrativeArea rdfs:subClassOf ?mid .
        ?relatedAdministrativeArea rdfs:subClassOf ?mid .
    } UNION {
        ?administrativeArea geo:sfContains ?relatedAdministrativeArea .
    } UNION {
        ?administrativeArea geo:sfEquals ?relatedAdministrativeArea .
    } UNION {
        ?administrativeArea geo:sfIntersects ?relatedAdministrativeArea .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn-system: <http://purl.oclc.org/NET/ssn-system#>

SELECT DISTINCT ?systemProperty
WHERE {
    { ?systemProperty rdfs:subClassOf* ssn-system:SystemProperty }
    UNION
    { ?systemProperty rdf:type owl:Class . 
      ?systemProperty rdfs:subClassOf* ssn-system:SystemProperty }
}

PREFIX ssn-system: <http://purl.oclc.org/NET/ssnx/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property 
WHERE {
    { ?property rdfs:subClassOf ssn-system:SystemProperty . 
      ?property rdf:type owl:Class .
      FILTER (?property = ssn-system:Accuracy) }
    UNION
    { ?property rdfs:subClassOf ssn-system:SystemProperty . 
      ?property rdf:type owl:Class .
      FILTER (?property = ssn-system:Precision) }
}

PREFIX ssn-system: <http://www.semanticweb.org/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?property
WHERE {
    :HumanUser rdfs:subClassOf foaf:Person .
    ?property rdfs:subClassOf ssn-system:SystemProperty .
    FILTER NOT EXISTS { 
        ?otherProperty rdfs:subClassOf ?property . 
        ?otherProperty rdfs:subClassOf ssn-system:SystemProperty .
    }
}

PREFIX ssn-system: <http://purl.oclc.org/NET/ssn-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?systemProperty1 ?relation ?systemProperty2
WHERE {
    ?systemProperty1 rdfs:subClassOf ssn-system:SystemProperty .
    ?systemProperty2 rdfs:subClassOf ssn-system:SystemProperty .
    FILTER (?systemProperty1 != ?systemProperty2) .
    { 
        ?systemProperty1 rdfs:subClassOf ?mid .
        ?mid rdfs:subClassOf ?systemProperty2 .
    } UNION {
        ?systemProperty1 owl:equivalentClass ?systemProperty2 .
    } UNION {
        ?systemProperty1 rdfs:subClassOf+ ?systemProperty2 .
    }
}

PREFIX ssn-system: <http://www.semanticweb.org/ssn/system/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?humanUser ?systemProperty
WHERE {
    ?humanUser rdf:type :HumanUser .
    ?systemProperty rdf:type ssn-system:SystemProperty .
    FILTER NOT EXISTS { 
        ?humanUser ?p ?systemProperty . 
        FILTER (?p = rdf:type)
    }
}

PREFIX ssn-system: <http://www.semanticweb.org/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?superClass
WHERE {
    ?property rdf:type owl:Class .
    ?property rdfs:subClassOf ssn-system:SystemProperty .
    OPTIONAL { 
        ?property rdfs:subClassOf ?superClass . 
        FILTER (?superClass != ssn-system:SystemProperty)
    }
}

PREFIX ssn-system: <http://purl.oclc.org/NET/ssnx/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?systemProperty ?otherProperty
WHERE {
    ?systemProperty rdfs:subClassOf|rdf:type ssn-system:SystemProperty .
    ?otherProperty rdf:type owl:Class .
    FILTER NOT EXISTS { 
        ?otherProperty rdfs:subClassOf|rdf:type ssn-system:SystemProperty 
    }
    FILTER (?systemProperty != ?otherProperty)
}

PREFIX ssn-system: <http://purl.oclc.org/NET/ssnx/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX ssn: <http://purl.oclc.org/NET/ssnx/>

SELECT ?property ?systemProperty
WHERE {
    ?property rdf:type ssn:Property .
    ?systemProperty rdf:type ssn-system:SystemProperty .
    FILTER NOT EXISTS {
        ?property owl:equivalentClass ?systemProperty .
    }
    FILTER (?property != ?systemProperty)
    FILTER (EXISTS {
        ?property rdfs:subClassOf ?parent .
        ?systemProperty rdfs:subClassOf ?parent
    } || ?property = ssn:Property && ?systemProperty = ssn-system:SystemProperty)
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?range 
WHERE {
    geo:sfContains rdfs:range ?range.
}

PREFIX geo: <http://www.opengis.net/ont/geosparql>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    { ?property rdfs:isDefinedBy <http://www.opengis.net/ont/geosparql> }
    UNION
    { ?property rdf:type owl:ObjectProperty ; rdfs:isDefinedBy <http://www.opengis.net/ont/geosparql> }
    UNION
    { ?property rdf:type owl:DatatypeProperty ; rdfs:isDefinedBy <http://www.opengis.net/ont/geosparql> }
    UNION
    { ?property rdf:type owl:FunctionalProperty ; rdfs:isDefinedBy <http://www.opengis.net/ont/geosparql> }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?domain
WHERE {
    geo:sfContains rdfs:domain ?domain.
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?relationship
WHERE {
    ?relationship rdf:type owl:ObjectProperty .
    FILTER (?relationship = geo:sfContains || ?relationship = geo:sfWithin) .
    { 
        ?relationship rdfs:domain geo:SpatialObject .
        ?relationship rdfs:range geo:SpatialObject .
    } UNION {
        ?relationship rdfs:domain geo:SpatialObject .
        ?relationship rdfs:range geo:SpatialObject .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX : <http://example.com/ontology/>

SELECT DISTINCT ?property
WHERE {
    { 
        ?property rdfs:domain :Device .
    } UNION {
        ?property rdfs:subPropertyOf ?superProperty .
        ?superProperty rdfs:domain :Device .
    }
    FILTER (?property != rdf:type && ?property != owl:topObjectProperty)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX : <http://example.com/ontology/>

SELECT ?property
WHERE {
    {
        ?property rdf:type owl:DatatypeProperty .
        ?property rdfs:domain :Service .
    }
    UNION
    {
        ?property rdf:type owl:DatatypeProperty .
        ?property rdfs:domain ?superClass .
        ?superClass rdfs:subClassOf :Service .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX : <http://example.org/>

SELECT ?property ?value
WHERE {
    { 
        ?device a :Device .
        ?device ?property ?value .
        FILTER(isLiteral(?value))
        FILTER(datatype(?value) = xsd:string)
    } UNION {
        ?service a :Service .
        ?service ?property ?value .
        FILTER(isLiteral(?value))
        FILTER(datatype(?value) = xsd:string)
    }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX iot: <http://iot.linkeddata.es/def/wot#>

SELECT ?service
WHERE {
    ?device a :Device .
    { ?device rdfs:subClassOf sosa:Sensor . }
    UNION
    { ?device rdfs:subClassOf sosa:Actuator . }
    ?device :deviceName ?deviceName .
    ?service a :Service .
    ?service :serviceName ?serviceName .
    FILTER NOT EXISTS {
        ?service :relativeHref ?href .
        FILTER (NOT REGEX(?href, "^https?://"))
    }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX : <http://example.org/>

SELECT ?device
WHERE {
    ?device rdf:type :Device .
    {
        { 
            ?device sosa:hosts ?sensor1 . 
            ?device sosa:hosts ?sensor2 . 
            FILTER (?sensor1 != ?sensor2) .
            ?sensor1 rdf:type :Sensor .
            ?sensor2 rdf:type :Sensor .
        }
        UNION
        { 
            ?device sosa:hosts ?actuator1 . 
            ?device sosa:hosts ?actuator2 . 
            FILTER (?actuator1 != ?actuator2) .
            ?actuator1 rdf:type :Actuator .
            ?actuator2 rdf:type :Actuator .
        }
    }
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>

SELECT ?device ?property
WHERE {
    ?device ssn:hasProperty|ssn-system:hasOperatingRange|ssn-system:hasSystemCapability|ssn-system:hasSystemProperty|ssn-system:qualityOfObservation|ssn-system:hasSurvivalRange|ssn-system:hasSurvivalProperty|ssn-system:hasOperatingProperty ?property .
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?device
WHERE {
    ?device ssn:hasProperty [
        a ?property;
        rdfs:label "temperature"@en
    ].
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/systems/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?system ?property
WHERE {
    {
        ?system ssn-system:hasOperatingProperty ?property .
    } UNION {
        ?system ssn-system:hasSystemCapability ?property .
    } UNION {
        ?system ssn-system:hasSurvivalRange ?property .
    } UNION {
        ?system ssn-system:hasSurvivalProperty ?property .
    } UNION {
        ?system ssn-system:qualityOfObservation ?property .
    }
}

PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?condition ?property
WHERE {
    ?system ssn-system:inCondition ?condition .
    { 
        ?system ssn-system:hasSurvivalProperty ?property .
    } UNION {
        ?system ssn-system:hasOperatingRange ?property .
    }
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?system ?property ?capability ?operatingRange ?survivalRange ?interactsWith
WHERE {
    ?system a ssn-system:System .
    OPTIONAL { ?system ssn-system:hasSystemProperty ?property . }
    OPTIONAL { ?system ssn-system:hasSystemCapability ?capability . }
    OPTIONAL { ?system ssn-system:hasOperatingRange ?operatingRange . }
    OPTIONAL { ?system ssn-system:hasSurvivalRange ?survivalRange . }
    OPTIONAL { ?system :interactsUsing ?interactsWith . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?x
WHERE {
    ?y :describes ?x .
}

PREFIX s4bldg: <http://example.org/s4bldg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?space
WHERE {
    ?building s4bldg:hasSpace ?space .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX : <http://example.com/ontology/>
PREFIX s4bldg: <http://example.com/s4bldg/>
PREFIX ssn: <http://example.com/ssn/>

SELECT DISTINCT ?serviceOwner ?component
WHERE {
    ?petitioner rdf:type :Petitioner .
    ?petitioner :requestedService ?requestedService .
    ?serviceOwner :servicePetitioner ?petitioner .
    ?serviceOwner :hasComponent ?component .
    FILTER NOT EXISTS {
        ?unfulfilledService rdf:type :Service .
        ?petitioner :requestedService ?unfulfilledService .
        FILTER NOT EXISTS {
            ?component :isComponentOf ?unfulfilledService .
        }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?inverseProperty
WHERE {
    :hasComponent owl:inverseOf ?inverseProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>

SELECT DISTINCT ?property
WHERE {
    { ?property rdf:type owl:ObjectProperty }
    UNION
    { ?property rdf:type owl:DatatypeProperty }
    UNION
    { ?property rdf:type owl:FunctionalProperty }
    UNION
    { ?property rdf:type owl:InverseFunctionalProperty }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?class1 ?property ?class2
WHERE {
    ?class1 rdf:type owl:Class .
    ?property rdf:type owl:ObjectProperty .
    ?class2 rdf:type owl:Class .
    FILTER (?class1 != ?class2) .
    { 
        ?class1 rdfs:subClassOf ?class2 .
    } UNION {
        ?property rdfs:domain ?class1 .
        ?property rdfs:range ?class2 .
    } UNION {
        ?property owl:inverseOf ?invProperty .
        ?invProperty rdfs:domain ?class2 .
        ?invProperty rdfs:range ?class1 .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX : <http://example.com/ontology/>

SELECT DISTINCT ?type
WHERE {
    ?type rdf:type owl:Class .
    FILTER NOT EXISTS { ?type rdfs:subClassOf* :EcosystemDescription }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?thing ?relatedEntity ?relation
WHERE {
    ?thing rdf:type <http://iot.linkeddata.es/def/wot#Thing> .
    {
        { ?thing :represents ?relatedEntity . BIND(:represents AS ?relation) }
        UNION
        { ?relatedEntity :isInvolvedIn ?thing . BIND(:isInvolvedIn AS ?relation) }
        UNION
        { ?relatedEntity :involves ?thing . BIND(:involves AS ?relation) }
        UNION
        { ?thing :isEcosystemDescribedBy ?relatedEntity . BIND(:isEcosystemDescribedBy AS ?relation) }
        UNION
        { ?thing :aboutProperty ?relatedEntity . BIND(:aboutProperty AS ?relation) }
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?creator
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:creator ?creator .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?creator ?contributor ?role 
WHERE {
    {
        <http://iot.linkeddata.es/def/core#> dcterms:creator ?person .
        BIND("Creator" AS ?role)
    } UNION {
        <http://iot.linkeddata.es/def/core#> dcterms:contributor ?person .
        BIND("Contributor" AS ?role)
    }
    BIND(COALESCE(?person, <http://www.garcia-castro.com/foaf.rdf#me>) AS ?creator)
    BIND(COALESCE(?person, <http://www.oeg-upm.net/index.php/en/universitystaff/402-fserena/>) AS ?contributor)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?publisher ?role
WHERE {
    <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher .
    OPTIONAL { 
        ?publisher rdf:type ?role .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?publisher ?website
WHERE {
    <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher .
    OPTIONAL { ?publisher foaf:homepage ?website . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?hasMinValue ?hasMaxValue
WHERE {
    :hasMinValue rdf:type owl:ObjectProperty .
    :hasMaxValue rdf:type owl:ObjectProperty .
    :hasMinValue rdfs:subPropertyOf rdf:value .
    :hasMaxValue rdfs:subPropertyOf rdf:value .
    OPTIONAL { :hasMinValue rdfs:domain ?minDomain . }
    OPTIONAL { :hasMaxValue rdfs:domain ?maxDomain . }
    OPTIONAL { :hasMinValue rdfs:range ?minRange . }
    OPTIONAL { :hasMaxValue rdfs:range ?maxRange . }
    BIND(:hasMinValue AS ?hasMinValue)
    BIND(:hasMaxValue AS ?hasMaxValue)
}
